// Parse Gorgias macros and prepare for Supabase
const macros = $input.all();
const parsed = [];

for (const item of macros) {
  const macroData = item.json.data || item.json;

  // Handle both single macro and array of macros
  const macrosArray = Array.isArray(macroData) ? macroData : [macroData];

  for (const macro of macrosArray) {
    // Infer category from macro name and content
    let category = 'general';
    const name = (macro.name || '').toLowerCase();
    const subject = (macro.subject || '').toLowerCase();
    const body = (macro.body_text || macro.body_html || '').toLowerCase();
    const combined = `${name} ${subject} ${body}`.substring(0, 500);

    if (combined.includes('refund') || combined.includes('money back')) {
      category = 'refund';
    } else if (combined.includes('ship') || combined.includes('delivery') || combined.includes('tracking')) {
      category = 'shipping';
    } else if (combined.includes('technical') || combined.includes('troubleshoot') || combined.includes('fix')) {
      category = 'technical';
    } else if (combined.includes('billing') || combined.includes('payment') || combined.includes('invoice')) {
      category = 'billing';
    } else if (combined.includes('order') || combined.includes('purchase')) {
      category = 'order';
    } else if (combined.includes('return') || combined.includes('rma')) {
      category = 'returns';
    } else if (combined.includes('warranty') || combined.includes('guarantee')) {
      category = 'warranty';
    } else if (combined.includes('apology') || combined.includes('sorry')) {
      category = 'apology';
    } else if (combined.includes('thank') || combined.includes('appreciate')) {
      category = 'gratitude';
    }

    // Extract body text (prefer plain text over HTML)
    let bodyContent = macro.body_text || '';
    if (!bodyContent && macro.body_html) {
      // Simple HTML to text conversion
      bodyContent = macro.body_html
        .replace(/<[^>]*>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    }

    parsed.push({
      json: {
        macro_id: macro.id,
        macro_name: macro.name,
        macro_description: macro.subject || macro.name,
        macro_content: bodyContent.substring(0, 5000), // Limit to 5000 chars
        category: category,
        usage_count: 0, // Will be updated from ticket data later
        is_active: macro.active !== false,
        updated_at: new Date().toISOString()
      }
    });
  }
}

console.log(`✅ Parsed ${parsed.length} macros`);
return parsed;

// Calculate sync statistics
const items = $input.all();

const stats = {
  total_processed: items.length,
  sync_timestamp: new Date().toISOString(),
  workflow: 'gorgias_macros_sync',
  status: 'success'
};

console.log('═══════════════════════════════════════');
console.log('✅ Macros Sync Complete');
console.log(`   Total macros synced: ${stats.total_processed}`);
console.log(`   Timestamp: ${stats.sync_timestamp}`);
console.log('═══════════════════════════════════════');

return [{ json: stats }];

